local jest_config_names = {
	"jest.config.ts",
	"jest.config.js",
	"jest.config.mjs",
	"jest.config.cjs",
}

local function nearest_jest_config(file)
	if not file or file == "" then
		return nil
	end

	return vim.fs.find(jest_config_names, {
		path = vim.fs.dirname(vim.fs.normalize(file)),
		upward = true,
	})[1]
end

