					jestCommand = "yarn jest",
					jestConfigFile = function(file)
						return nearest_jest_config(file) or "jest.config.ts"
					end,
					cwd = function(file)
						local config = nearest_jest_config(file)
						return config and vim.fs.dirname(config) or vim.uv.cwd()
					end,
